1	package com.loja.checkout.servico;
2	
3	import com.loja.checkout.CalculoCheckoutException;
4	import com.loja.checkout.api.ItemRequest;
5	import com.loja.checkout.api.ResumoCheckoutRequest;
6	import com.loja.checkout.api.ResumoCheckoutResponse;
7	import com.loja.checkout.dominio.Cupom;
8	import com.loja.checkout.dominio.Dinheiro;
9	import com.loja.checkout.dominio.FormaPagamento;
10	import com.loja.checkout.dominio.ItemPedido;
11	import com.loja.checkout.dominio.ModalidadeEntrega;
12	import com.loja.checkout.dominio.NivelClube;
13	import com.loja.checkout.dominio.Regiao;
14	import com.loja.checkout.dominio.ResultadoPagamento;
15	import org.springframework.stereotype.Service;
16	
17	import java.math.BigDecimal;
18	import java.util.List;
19	
20	@Service
21	public class CalculoCheckoutService {
22	
23	    public ResumoCheckoutResponse calcular(ResumoCheckoutRequest request) {
24	        List<ItemPedido> itens = converterItens(request);
25	        validarItens(itens);
26	
27	        NivelClube nivelClube = parseEnum(NivelClube.class, request.nivelClube(), "NIVEL_CLUBE_INVALIDO");
28	        Regiao regiao = parseEnum(Regiao.class, request.regiao(), "REGIAO_INVALIDA");
29	        ModalidadeEntrega modalidade = parseEnum(ModalidadeEntrega.class, request.modalidadeEntrega(), "MODALIDADE_INVALIDA");
30	
31	        BigDecimal pesoTotal = pesoTotal(itens);
32	        if (!modalidade.disponivel(pesoTotal)) {
33	            throw new CalculoCheckoutException("MODALIDADE_INDISPONIVEL");
34	        }
35	
36	        BigDecimal subtotalProdutos = Dinheiro.arredondar(subtotalProdutos(itens));
37	
38	        BigDecimal freteBase = Dinheiro.arredondar(modalidade.frete(itens, pesoTotal));
39	        BigDecimal frete = nivelClube.freteGratis() ? BigDecimal.ZERO.setScale(2) : freteBase;
40	
41	        Cupom cupom = null;
42	        if (request.cupom() != null) {
43	            cupom = parseEnum(Cupom.class, request.cupom(), "CUPOM_INVALIDO");
44	            if (!cupom.aplicavel(subtotalProdutos, itens)) {
45	                throw new CalculoCheckoutException("CUPOM_NAO_APLICAVEL");
46	            }
47	        }
48	        BigDecimal descontoCupom = cupom == null
49	                ? BigDecimal.ZERO.setScale(2)
50	                : Dinheiro.arredondar(cupom.desconto(subtotalProdutos, itens, frete));
51	
52	        BigDecimal seguro = Dinheiro.arredondar(regiao.percentualSeguro().multiply(subtotalProdutos));
53	
54	        BigDecimal totalPedido = Dinheiro.arredondar(
55	                subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro));
56	
57	        FormaPagamento formaPagamento = parseEnum(FormaPagamento.class, request.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
58	
59	        int parcelas = request.parcelas() == null ? 1 : request.parcelas();
60	        if (!formaPagamento.parcelasValidas(parcelas)) {
61	            throw new CalculoCheckoutException("PARCELAMENTO_INVALIDO");
62	        }
63	        if (!formaPagamento.disponivel(totalPedido)) {
64	            throw new CalculoCheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
65	        }
66	
67	        ResultadoPagamento resultadoPagamento = formaPagamento.calcular(totalPedido, parcelas);
68	
69	        BigDecimal creditoProximaCompra = Dinheiro.arredondar(
70	                nivelClube.percentualCredito().multiply(subtotalProdutos));
71	        boolean brinde = nivelClube.temBrinde(subtotalProdutos);
72	
73	        return new ResumoCheckoutResponse(
74	                subtotalProdutos,
75	                descontoCupom,
76	                frete,
77	                modalidade.prazoDias(),
78	                seguro,
79	                resultadoPagamento.ajuste(),
80	                resultadoPagamento.totalFinal(),
81	                parcelas,
82	                resultadoPagamento.valorParcela(),
83	                creditoProximaCompra,
84	                brinde
85	        );
86	    }
87	
88	    private List<ItemPedido> converterItens(ResumoCheckoutRequest request) {
89	        if (request.itens() == null) {
90	            return List.of();
91	        }
92	        return request.itens().stream()
93	                .map(this::converterItem)
94	                .toList();
95	    }
96	
97	    private ItemPedido converterItem(ItemRequest item) {
98	        int quantidade = item.quantidade() == null ? 0 : item.quantidade();
99	        return new ItemPedido(item.nome(), item.precoUnitario(), quantidade, item.pesoKg());
100	    }
101	
102	    private void validarItens(List<ItemPedido> itens) {
103	        if (itens.isEmpty() || itens.stream().anyMatch(item -> !item.valido())) {
104	            throw new CalculoCheckoutException("PEDIDO_INVALIDO");
105	        }
106	    }
107	
108	    private BigDecimal subtotalProdutos(List<ItemPedido> itens) {
109	        return itens.stream()
110	                .map(ItemPedido::totalItem)
111	                .reduce(BigDecimal.ZERO, BigDecimal::add);
112	    }
113	
114	    private BigDecimal pesoTotal(List<ItemPedido> itens) {
115	        return itens.stream()
116	                .map(ItemPedido::pesoTotal)
117	                .reduce(BigDecimal.ZERO, BigDecimal::add);
118	    }
119	
120	    private <T extends Enum<T>> T parseEnum(Class<T> tipo, String valor, String codigoErro) {
121	        if (valor == null) {
122	            throw new CalculoCheckoutException(codigoErro);
123	        }
124	        try {
125	            return Enum.valueOf(tipo, valor);
126	        } catch (IllegalArgumentException e) {
127	            throw new CalculoCheckoutException(codigoErro);
128	        }
129	    }
130	}
